  function depth(i) {
    if (i >= arr.length || arr[i] === null) return 0;
    return 1 + Math.max(depth(2 * i + 1), depth(2 * i + 2));
  }
  return depth(0);
}

function solve(arr) {
  if (!arr.length) return 0;
  return Math.floor(Math.log2(arr.length)) + 1;
}

